#!/bin/sh
set -eu
# One live-core build at a time and never during a test run (web/test-lock.mjs): re-run holding the build lock. It waits
# for running tests, and tests started meanwhile wait for the build. CORE_OUT builds do not touch the live core.
if [ -z "${SSX_BUILD_LOCK_HELD:-}" ] && [ -z "${CORE_OUT:-}" ]; then exec node "$(dirname "$0")/test-lock.mjs" build -- "$0" "$@"; fi
cd "$(dirname "$0")/.."
mkdir -p web/runtime
# Build into a private folder, then swap both files in together: concurrent readers (tests, the dev
# server) must never see a new core.js with an old core.wasm or a half-written file.
out=${CORE_OUT:-web/runtime} # CORE_OUT: build elsewhere (a test core) without touching the live one
mkdir -p "$out"
tmp=$(mktemp -d "$out/.build.XXXXXX")
# EMXX: the Emscripten 6.0.9 em++ (default: the emsdk under local/vendor; tools/setup_from_iso.py passes its own)
EMXX=${EMXX:-local/vendor/emsdk/upstream/emscripten/em++}
trap 'rm -rf "$tmp"' EXIT
python3 web/generate-controllers.py
# The rider-context snapshot's registry (web/generate-snapshot-registry.mjs, docs/replay.md §2a; pv eventReturnInWorld (b): the
# in-world replay's snapshots), compiled into every core.
node web/generate-snapshot-registry.mjs >/dev/null
# Engine code lifted from the ELF (engine/generated, git-ignored like web/generated: made from your own disc in
# local/disc, never published). Generated when missing; rerun the tools after changing them.
py=python3; [ -x .venv/bin/python3 ] && py=.venv/bin/python3 # the lift needs rabbitizer
[ -f engine/generated/set_piece_particle_bounds.inc ] || "$py" tools/test_set_piece_particles_lift.py
[ -f engine/generated/lighting_math.hpp ] || python3 tools/generate_lighting_math.py
[ -f engine/generated/irradiance_transform.hpp ] || python3 tools/generate_irradiance_transform.py
# -flto (docs/sim-performance.md "LTO"): whole-program optimisation across the core's sources, ~5% of a tick; wasm has no FMA and the
# sources keep -ffp-contract=off, so arithmetic is unchanged (captures, differential harness). check-rider-globals.mjs reads the LTO map.
"$EMXX" -DSSX_SNAPSHOT_REGISTRY web/core.cpp web/rail_bridge.cpp web/race_bridge.cpp web/race_world.cpp web/world_bridge.cpp web/prediction_bridge.cpp web/animation_bridge.cpp web/attribute_bridge.cpp web/environment_bridge.cpp web/rider_lighting_bridge.cpp web/generated/environment_lighting.cpp web/generated/snow_particles.cpp web/generated/snow_context.cpp web/generated/snow_emission.cpp web/generated/wake_row.cpp web/generated/wake_input.cpp web/generated/wake_control.cpp web/generated/wake_render.cpp web/generated/animation_graph.cpp web/generated/jump_motion.cpp web/generated/ground_motion.cpp web/generated/ground_pose_motion.cpp web/generated/soft_collision_control.cpp web/generated/stance_restore.cpp web/generated/reset_route.cpp web/generated/reset_placement.cpp web/generated/npc_path.cpp web/generated/npc_input.cpp web/generated/npc_air.cpp web/generated/air_motion.cpp web/generated/air_trajectory.cpp web/generated/air_alignment.cpp web/generated/air_control.cpp web/generated/air_entry.cpp web/generated/air_animation_selector.cpp web/generated/orientation_motion.cpp web/generated/landing_motion.cpp web/generated/upper_reaction.cpp web/generated/grab_score.cpp web/generated/passive_air_control.cpp web/generated/race_event.cpp web/generated/boost_control.cpp web/generated/boost_award.cpp web/generated/trick_identity.cpp web/generated/trick_commit.cpp engine/trick_history.cpp engine/trick_bonus.cpp engine/score_object.cpp engine/original_input.cpp engine/original_input_provider.cpp engine/animation_motion.cpp engine/rider_pose_motion.cpp engine/animation_sequence.cpp engine/animation_cycle.cpp engine/animation_events.cpp engine/animation_variant.cpp engine/ground_animation_control.cpp engine/grab_lifecycle.cpp engine/attack_control.cpp web/rider_context.cpp web/rider_tls.S -Iengine -Iweb/third_party/nlohmann -std=c++20 -O3 -flto -fwasm-exceptions -sWASM_LEGACY_EXCEPTIONS=1 -sEXPORT_EXCEPTION_HANDLING_HELPERS -ffp-contract=off -matomics -mbulk-memory -ftls-mode