node web/patch-rider-tls.mjs "$tmp/core.wasm" "$tmp/core.js" "$tmp/core.map"
# Every mutable global of the core must be per rider (RIDER_LOCAL) or on the shared allowlist: fails on a new plain one.
node web/check-rider-globals.mjs "$tmp/core.map"
# Every thread-local variable is in the rider-context snapshot's registry or classified (web/snapshot-policy.mjs, docs/replay.md §2a).
node web/check-snapshot-registry.mjs "$tmp/core.map"
[ -n "${CORE_OUT:-}" ] && cp "$tmp/core.map" "$out/core.map" # a scratch build keeps its link map (the TLS layout: web/snapshot tooling)
mv -f "$tmp/core.wasm" "$out/core.wasm" && mv -f "$tmp/core.js" "$out/core.js"
